// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {PENNY_BY_PENNY} from "../src/PENNY_BY_PENNY.sol";

contract InvMutTest is Test {
    PENNY_BY_PENNY c;
    function setUp() public { c = new PENNY_BY_PENNY(); }

    function testFuzz_property(uint256 newVal) public {
        uint256 before = c.MinSum();
        c.Initialized();
        vm.prank(address(0xBEEF));
        try c.SetMinSum(newVal) {
            assertTrue(c.MinSum() == before, "MinSum changed after initialization");
        } catch {
            assertTrue(c.MinSum() == before, "MinSum changed after initialization");
        }
    }
}
